import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import reservationService from '../../services/reservationService';
import PageHeader from '../../components/common/PageHeader';
import DataTable from '../../components/common/DataTable';
import StatusBadge from '../../components/common/StatusBadge';
import '../../components/common/shared.css';

const MyReservationsPage = () => {
  const navigate = useNavigate();
  const [reservations, setReservations] = useState([]);
  const [loading, setLoading]           = useState(true);
  const [cancelling, setCancelling]     = useState(null);

  const load = () => {
    setLoading(true);
    reservationService.getMyReservations()
      .then(setReservations)
      .catch(() => {})
      .finally(() => setLoading(false));
  };

  useEffect(() => { load(); }, []);

  const handleCancel = async (id) => {
    if (!window.confirm('Annuler cette réservation ?')) return;
    setCancelling(id);
    try {
      await reservationService.cancel(id);
      load();
    } catch (err) {
      alert(err.message || 'Erreur');
    } finally {
      setCancelling(null);
    }
  };

  const columns = [
    { key: 'room', label: 'Chambre', render: r => `Chambre ${r.room?.number ?? r.room_id}` },
    {
      key: 'check_in',
      label: 'Arrivée',
      render: r => new Date(r.check_in).toLocaleDateString('fr-FR'),
    },
    {
      key: 'check_out',
      label: 'Départ',
      render: r => new Date(r.check_out).toLocaleDateString('fr-FR'),
    },
    {
      key: 'total',
      label: 'Montant',
      render: r => r.total_price ? `${r.total_price} €` : '—',
    },
    {
      key: 'status',
      label: 'Statut',
      render: r => <StatusBadge status={r.status} />,
    },
  ];

  return (
    <div>
      <PageHeader
        title="Mes réservations"
        subtitle="Historique complet de vos séjours"
        action={
          <button className="btn btn--gold" onClick={() => navigate('/client/rooms')}>
            + Nouvelle réservation
          </button>
        }
      />

      <DataTable
        columns={columns}
        data={reservations}
        loading={loading}
        empty="Vous n'avez encore aucune réservation."
        actions={row => (
          <div style={{ display: 'flex', gap: 6, justifyContent: 'flex-end' }}>
            {row.status === 'pending' && (
              <button
                className="btn btn--sm btn--danger"
                disabled={cancelling === row.id}
                onClick={() => handleCancel(row.id)}
              >
                Annuler
              </button>
            )}
            {row.invoice_id && (
              <button
                className="btn btn--sm btn--outline"
                onClick={() => navigate('/client/invoices')}
              >
                Facture
              </button>
            )}
          </div>
        )}
      />
    </div>
  );
};

export default MyReservationsPage;
